#!/usr/bin/env python3
"""Self-contained offline SVG geographic explorer; no CDN, tiles or dependencies in output."""
from pathlib import Path
import pandas as pd,json,html
ROOT=Path(__file__).resolve().parents[2]
MARKETS={'surabaya':[112.64,-7.38,112.84,-7.18],'medan':[98.59,3.48,98.77,3.69],'bandung':[107.51,-6.99,107.74,-6.82],'palembang':[104.66,-3.07,104.85,-2.88]}
def main():
 p=pd.read_csv(ROOT/'workstreams/providers/provider_inventory.csv').fillna('');b=pd.read_csv(ROOT/'workstreams/branches/routing_destinations.csv').fillna('');o=pd.read_csv(ROOT/'workstreams/context/otoxpert_official_inventory.csv').fillna('');a=pd.read_csv(ROOT/'workstreams/routing/supplement/combined_origin_accessibility.csv' if (ROOT/'workstreams/routing/supplement/combined_origin_accessibility.csv').exists() else ROOT/'workstreams/routing/output/origin_accessibility.csv');a=a.astype(object).where(a.notna(),'');a['market']=a.market.str.lower()
 rows={}
 for m,bbox in MARKETS.items():
  w,s,e,n=bbox;pp=p[(p.market.str.lower()==m)&p.longitude.between(w-.08,e+.08)&p.latitude.between(s-.08,n+.08)]
  if 'eligible_candidate' in pp:pp=pp[pp.eligible_candidate.astype(str).str.lower().isin(['true','1'])]
  points=[]
  for _,r in pp.iterrows():points.append({'kind':'independent','name':str(r['name']),'lon':float(r.longitude),'lat':float(r.latitude),'detail':'Mapped repair/service candidate. Toyota/model/job capability unverified.','source':'Overture Places 2026-10-21.0'})
  dd=pd.read_csv(ROOT/f'workstreams/routing/inputs/{m}_destinations.csv').astype(object).fillna('')
  for _,r in dd[dd.kind=='auto2000'].iterrows():
   if r.longitude!='' and r.latitude!='':points.append({'kind':'auto2000','name':r['name'],'lon':float(r.longitude),'lat':float(r.latitude),'detail':'Official general-workshop listing. Entrance and selected job not field verified.','source':r.source_url})
  for _,r in o[o.longitude.between(w-.08,e+.08)&o.latitude.between(s-.08,n+.08)].iterrows():points.append({'kind':'otoxpert','name':r['name'],'lon':float(r.longitude),'lat':float(r.latitude),'detail':f'Official listing; operator: {r.operator}. Local job/model eligibility unconfirmed.','source':r.source_url})
  sdpath=ROOT/'workstreams/providers/shopanddrive_official_study.csv'
  if sdpath.exists():
   sd=pd.read_csv(sdpath).fillna('');sd=sd[sd.longitude.between(w-.08,e+.08)&sd.latitude.between(s-.08,n+.08)]
   for _,r in sd.iterrows():points.append({'kind':'oil_chain','name':r['name'],'lon':float(r.longitude),'lat':float(r.latitude),'detail':'Official Shop & Drive listing; network oil/filter offering. Exact Toyota fitment and slot unconfirmed.','source':r.source_url})
  rows[m]={'bbox':bbox,'points':points,'origins':a[a.market==m].to_dict('records')}
 template=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auto2000 Geographic Evidence Explorer</title><style>
:root{font-family:system-ui,sans-serif;color:#182e35;background:#fbfaf6}body{margin:0}header{padding:24px 30px 16px;border-bottom:1px solid #ccd6d5}h1{font-size:25px;margin:0 0 8px}p{max-width:1040px;line-height:1.5;margin:8px 0}main{padding:20px 30px}.controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:14px}select,button{padding:8px;border:1px solid #a8b6b6;background:white;border-radius:4px}label{font-size:14px}.layout{display:grid;grid-template-columns:minmax(0,3fr) minmax(230px,1fr);gap:20px}svg{width:100%;height:65vh;min-height:420px;background:#f1f1e9;border:1px solid #a8b6b6;touch-action:none}aside{background:white;border:1px solid #ccd6d5;padding:18px;line-height:1.55;font-size:14px}.small{font-size:12px;color:#506367}h2{font-size:17px}#tip{white-space:pre-line;overflow-wrap:anywhere}svg circle,svg rect.origin{cursor:pointer}.swatch{display:inline-block;width:12px;height:12px;margin-right:4px}.notes{font-size:13px;border-top:1px solid #ccd6d5;padding-top:14px;margin-top:16px}@media(max-width:800px){.layout{grid-template-columns:1fr}header,main{padding:16px}svg{height:55vh}}
</style></head><body><header><h1>Auto2000 geographic evidence explorer</h1><p>Four bounded study windows. Explore public provider records and modelled travel from sampled grid origins. This file works offline and uses no external map tiles.</p></header><main><div class="controls"><label>Market <select id="market"></select></label><label>Scenario <select id="scenario"><option value="snap_le_250m">Both endpoints snap ≤250 m</option><option value="all_routed">All routed</option></select></label><label>Origin colour <select id="metric"><option value="gap">Additional minutes to Auto2000</option><option value="auto2000">Nearest Auto2000 minutes</option><option value="independent">Nearest repair/service candidate minutes</option><option value="collected_advertised_oil_channels">Advertised oil-channel minutes</option><option value="oilgap">Additional minutes vs oil channels</option><option value="none">Hide origins</option></select></label><label><input type="checkbox" id="showauto" checked> Auto2000</label><label><input type="checkbox" id="showgarage" checked> Repair/service candidates</label><label><input type="checkbox" id="showox" checked> OtoXpert</label><label><input type="checkbox" id="showsd" checked> Shop &amp; Drive</label><button id="reset">Reset view</button></div><div class="layout"><svg id="map" viewBox="0 0 900 700" role="img" aria-label="Interactive geographic point map"></svg><aside><h2 id="heading">Inspect a record</h2><div id="tip">Click a provider or origin to inspect its evidence and modelled access. Drag to pan; use the mouse wheel to zoom.</div><h2>Legend</h2><p><span class="swatch" style="background:#d5523a"></span>Auto2000 general-workshop listing<br><span class="swatch" style="background:#236d80"></span>Mapped repair/service candidate<br><span class="swatch" style="background:#aa8135"></span>OtoXpert listing<br><span class="swatch" style="background:#665496"></span>Shop &amp; Drive listing</p><p id="scale"></p><p class="small">The dashed outline is the origin-study rectangle. It is not an administrative boundary. Longitude and latitude use WGS84.</p></aside></div><div class="notes"><strong>How to interpret this map:</strong> Grid points are computational origins, not customer homes. The default ≤250 m snapping screen can remove paired results; grey squares indicate missing access values, not zero travel time. Mapped repair/service records do not establish equivalent Toyota/job capability. OSRM duration is a model output, not measured traffic or appointment availability. Positive additional minutes mean Auto2000 is slower to reach than the nearest listed mapped candidate; this does not predict switching or gross profit. Provider retrieval extends beyond the origin rectangle, but inventories remain finite and incomplete.<br><br><strong>Sources:</strong> Official Auto2000, OtoXpert and Shop &amp; Drive directories retrieved 14 November 2026; Overture Maps Places release 2026-10-21.0; OSRM driving responses and source snapshots in the accompanying ZIP. Original attribution and licensing records are retained there. This analytical explorer contains no road basemap.</div></main><script>
const DATA=__DATA__;const svg=document.querySelector('#map'),sel=document.querySelector('#market'),metric=document.querySelector('#metric'),scenario=document.querySelector('#scenario');const NS='http://www.w3.org/2000/svg';let view=[0,0,900,700],drag=null;
Object.keys(DATA).forEach(m=>{let o=document.createElement('option');o.value=m;o.textContent=m[0].toUpperCase()+m.slice(1);sel.appendChild(o)});
function el(tag,attrs,text){let e=document.createElementNS(NS,tag);for(let k in attrs)e.setAttribute(k,attrs[k]);if(text!==undefined)e.textContent=text;return e}
function safe(v){return typeof v==='number'&&Number.isFinite(v)}function minutes(v){return safe(v)?(v/60).toFixed(1)+' min':'Not identified'}
function inspect(title,text){document.querySelector('#heading').textContent=title;document.querySelector('#tip').textContent=text}
function color(v,mode){if(!safe(v))return '#aaa';if(mode==='gap'||mode==='oilgap'){let t=Math.min(1,Math.abs(v)/(v<0?10:30)),base=[235,235,226],end=v<0?[40,110,150]:[185,50,35];let c=base.map((b,i)=>Math.round(b+(end[i]-b)*t));return `rgb(${c.join(',')})`}let t=Math.min(1,v/40);return `rgb(${Math.round(205-175*t)},${Math.round(225-120*t)},${Math.round(225-100*t)})`}
function draw(){svg.innerHTML='';let d=DATA[sel.value],b=d.bbox,w=b[0]-.025,e=b[2]+.025,s=b[1]-.025,n=b[3]+.025;let x=lon=>65+(lon-w)/(e-w)*770,y=lat=>640-(lat-s)/(n-s)*580;for(let i=0;i<=5;i++){let lo=w+i*(e-w)/5,la=s+i*(n-s)/5;svg.appendChild(el('line',{x1:x(lo),x2:x(lo),y1:60,y2:640,stroke:'#d9ded7'}));svg.appendChild(el('text',{x:x(lo),y:665,'text-anchor':'middle','font-size':12,fill:'#506367'},lo.toFixed(3)));svg.appendChild(el('line',{x1:65,x2:835,y1:y(la),y2:y(la),stroke:'#d9ded7'}));svg.appendChild(el('text',{x:55,y:y(la)+4,'text-anchor':'end','font-size':12,fill:'#506367'},la.toFixed(3)))}
svg.appendChild(el('rect',{x:x(b[0]),y:y(b[3]),width:x(b[2])-x(b[0]),height:y(b[1])-y(b[3]),fill:'none',stroke:'#555','stroke-dasharray':'6 5'}));svg.appendChild(el('text',{x:835,y:35,'text-anchor':'end','font-size':16},'N ↑'));
let mode=metric.value;if(mode!=='none')d.origins.filter(o=>o.scenario===scenario.value).forEach(o=>{let raw=mode==='gap'?o.auto2000_minus_mapped_independent_seconds:mode==='oilgap'?o.auto2000_minus_advertised_oil_channels_seconds:o[mode+'_nearest_seconds'];let v=safe(raw)?raw/60:null;let r=el('rect',{class:'origin',x:x(o.longitude)-10,y:y(o.latitude)-10,width:20,height:20,fill:color(v,mode),stroke:'white','stroke-width':.8,opacity:.85});r.appendChild(el('title',{},o.origin_id+' | '+(v===null?'unknown':v.toFixed(1)+' min')));r.onclick=()=>inspect('Sampled origin '+o.origin_id,'Longitude: '+o.longitude.toFixed(5)+'\nLatitude: '+o.latitude.toFixed(5)+'\nNearest Auto2000: '+minutes(o.auto2000_nearest_seconds)+'\nNearest repair/service candidate: '+minutes(o.independent_nearest_seconds)+'\nNearest OtoXpert: '+minutes(o.otoxpert_nearest_seconds)+'\nNearest collected advertised oil channel: '+minutes(o.collected_advertised_oil_channels_nearest_seconds)+'\nAdditional minutes to Auto2000 vs mapped candidate: '+(safe(o.auto2000_minus_mapped_independent_seconds)?(o.auto2000_minus_mapped_independent_seconds/60).toFixed(1):'unknown')+'\nScenario: '+o.scenario+'. These are baseline modelled journeys, not observed customer travel.');svg.appendChild(r)});
d.points.forEach(p=>{let show=p.kind==='auto2000'?'showauto':p.kind==='otoxpert'?'showox':p.kind==='oil_chain'?'showsd':'showgarage';if(!document.querySelector('#'+show).checked)return;let r=el('circle',{cx:x(p.lon),cy:y(p.lat),r:p.kind==='independent'?3.3:7,fill:{auto2000:'#d5523a',independent:'#236d80',otoxpert:'#aa8135',oil_chain:'#665496'}[p.kind],stroke:p.kind==='independent'?'none':'white','stroke-width':1,opacity:p.kind==='independent'?.65:1});r.appendChild(el('title',{},p.name));r.onclick=()=>inspect(p.name,p.detail+'\n\nCoordinates: '+p.lat.toFixed(6)+', '+p.lon.toFixed(6)+'\n\nSource: '+p.source);svg.appendChild(r)});document.querySelector('#scale').textContent=(mode==='gap'||mode==='oilgap')?'Origin colours: blue = Auto2000 faster; pale = around equal; red = Auto2000 slower vs the selected comparison. Fixed scale −10 to +30 minutes; extremes saturated.':mode==='none'?'Origin squares hidden.':'Origin colours: pale to dark teal = 0 to 40 modelled minutes; longer values saturated.';svg.setAttribute('viewBox',view.join(' '))}
[sel,metric,scenario,...document.querySelectorAll('input')].forEach(e=>e.onchange=()=>{if(e===sel)view=[0,0,900,700];draw()});document.querySelector('#reset').onclick=()=>{view=[0,0,900,700];draw()};svg.onwheel=e=>{e.preventDefault();let z=e.deltaY>0?1.12:.89;view=[view[0]+view[2]*(1-z)/2,view[1]+view[3]*(1-z)/2,view[2]*z,view[3]*z];svg.setAttribute('viewBox',view.join(' '))};svg.onpointerdown=e=>{if(e.target===svg||e.target.tagName==='line'){drag={x:e.clientX,y:e.clientY,v:[...view]};svg.setPointerCapture(e.pointerId)}};svg.onpointermove=e=>{if(!drag)return;let r=svg.getBoundingClientRect();view[0]=drag.v[0]-(e.clientX-drag.x)*view[2]/r.width;view[1]=drag.v[1]-(e.clientY-drag.y)*view[3]/r.height;svg.setAttribute('viewBox',view.join(' '))};svg.onpointerup=()=>drag=null;draw();
</script></body></html>'''
 out=ROOT/'maps/Auto2000_Geographic_Explorer.html';out.parent.mkdir(exist_ok=True);out.write_text(template.replace('__DATA__',json.dumps(rows,separators=(',',':')).replace('</','<\\/')));print(out)
if __name__=='__main__':main()
